<?php require 'includes.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$_SESSION['user']['name']=trim($_POST['name']??me()['name']);$_SESSION['user']['phone']=trim($_POST['phone']??'');if(!empty($_FILES['photo']['tmp_name'])){if($_FILES['photo']['size']>2000000)flash('Photo must be under 2 MB.');else{$mime=mime_content_type($_FILES['photo']['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))flash('Use JPG, PNG or WebP.');else{$_SESSION['user']['photo']='data:'.$mime.';base64,'.base64_encode(file_get_contents($_FILES['photo']['tmp_name']));flash('Profile updated. Prototype crop/rotate controls are available in the photo preview.');}}}else flash('Profile updated.');header('Location: profile.php');exit;}head('Profile'); ?><h1>My profile</h1><form method="post" enctype="multipart/form-data" class="card narrow"><input type="hidden" name="csrf" value="<?= csrf() ?>"><?php if(!empty(me()['photo']))echo '<img class="avatar" src="'.e(me()['photo']).'" alt="Profile photo">'; ?><label>Profile photo<input type="file" name="photo" accept="image/*" capture="user"></label><label>Name<input name="name" value="<?= e(me()['name']) ?>"></label><label>Email<input value="<?= e(me()['email']) ?>" disabled></label><label>Phone<input name="phone" value="<?= e(me()['phone']??'') ?>"></label><div class="row"><button type="button" data-rotate>Rotate photo</button><button>Save profile</button></div></form><?php foot();
